use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex, PoisonError};

use crate::virt::error::VirtError;

/// Opaque, persistable machine identity.
///
/// Backends that mint hardware identities (Virtualization.framework's generic
/// machine identifier) write generated bytes back through this handle so the
/// caller can persist them across runs: check [`MachineIdentifier::was_generated`]
/// after machine construction and store [`MachineIdentifier::bytes`] if set.
#[derive(Debug, Clone, Default)]
pub struct MachineIdentifier {
    inner: Arc<Mutex<MachineIdentifierState>>,
}

#[derive(Debug, Default)]
struct MachineIdentifierState {
    bytes: Vec<u8>,
    generated: bool,
}

impl MachineIdentifier {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_bytes(bytes: Vec<u8>) -> Self {
        Self {
            inner: Arc::new(Mutex::new(MachineIdentifierState {
                bytes,
                generated: false,
            })),
        }
    }

    pub fn bytes(&self) -> Vec<u8> {
        self.lock().bytes.clone()
    }

    pub fn is_empty(&self) -> bool {
        self.lock().bytes.is_empty()
    }

    /// True when a backend generated a fresh identity during machine
    /// construction; the caller should persist [`MachineIdentifier::bytes`].
    pub fn was_generated(&self) -> bool {
        self.lock().generated
    }

    pub(crate) fn set_generated_bytes(&self, bytes: Vec<u8>) {
        let mut state = self.lock();
        state.bytes = bytes;
        state.generated = true;
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, MachineIdentifierState> {
        self.inner.lock().unwrap_or_else(PoisonError::into_inner)
    }
}

impl PartialEq for MachineIdentifier {
    fn eq(&self, other: &Self) -> bool {
        self.bytes() == other.bytes()
    }
}

impl Eq for MachineIdentifier {}

/// A block device attached to the guest.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DiskImage {
    pub path: PathBuf,
    pub read_only: bool,
}

/// A host directory exposed to the guest as a virtiofs share.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SharedDirectory {
    pub host_path: PathBuf,
    pub tag: String,
    pub read_only: bool,
}

/// A guest vsock port the host intends to use.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct VsockPort {
    /// Transitional preboot declaration used only by the krun core bridge.
    /// S7 removes this after the embedded backend makes ports fully dynamic.
    pub port: u32,
    pub mode: VsockPortMode,
}

/// Direction of a declared vsock port.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum VsockPortMode {
    /// Host dials the guest on this port (`connect_vsock`).
    Connect,
    /// Guest dials the host; the host accepts via `listen_vsock`.
    Listen,
}

/// Guest network attachment.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
#[non_exhaustive]
pub enum NetworkMode {
    #[default]
    None,
    UnixDatagram {
        peer_path: PathBuf,
        mac: [u8; 6],
    },
    UnixStream {
        path: PathBuf,
        mac: [u8; 6],
    },
    Tap {
        name: String,
        mac: [u8; 6],
    },
}

/// Terminal state of a machine observed through `wait`/`try_wait`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum VmExit {
    Stopped,
    StoppedWithError(String),
}

/// Options consumed only by the krun (Linux) backend; other backends ignore them.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct KrunOptions {
    /// Absolute path to the spawned `krun` helper binary.
    pub helper_path: Option<PathBuf>,
}

/// Options consumed only by the Virtualization.framework (macOS) backend.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct VzOptions {
    /// Mount a Rosetta directory share for x86_64 binary translation.
    pub rosetta: bool,
    /// Persisted machine identity; generated on first boot and written back.
    pub machine_identifier: Option<MachineIdentifier>,
}

/// Options consumed only by the mock backend (compiled with the
/// `mock-backend` feature); other backends ignore them.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct MockOptions {
    /// Absolute path to a scenario file scripting the mock's behavior.
    /// Absent means the happy-path default scenario.
    pub scenario: Option<PathBuf>,
}

/// Declarative description of a machine, independent of any backend.
///
/// Construct with [`VmConfig::builder`]. Building never fails; each backend
/// validates the configuration it is given when the machine is created.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct VmConfig {
    name: String,
    vm_id: String,
    base_directory: PathBuf,
    cpus: Option<usize>,
    memory_mib: Option<u64>,
    kernel_path: Option<PathBuf>,
    initramfs_path: Option<PathBuf>,
    kernel_cmdline: Vec<String>,
    nested_virtualization: bool,
    network: NetworkMode,
    disks: Vec<DiskImage>,
    mounts: Vec<SharedDirectory>,
    vsock_ports: Vec<VsockPort>,
    krun: KrunOptions,
    vz: VzOptions,
    mock: MockOptions,
}

impl VmConfig {
    pub fn builder(name: impl Into<String>) -> VmConfigBuilder {
        VmConfigBuilder {
            config: VmConfig {
                name: name.into(),
                ..VmConfig::default()
            },
        }
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn vm_id(&self) -> &str {
        &self.vm_id
    }

    pub fn base_directory(&self) -> &Path {
        &self.base_directory
    }

    pub fn cpus(&self) -> Option<usize> {
        self.cpus
    }

    pub fn memory_mib(&self) -> Option<u64> {
        self.memory_mib
    }

    pub fn kernel_path(&self) -> Option<&Path> {
        self.kernel_path.as_deref()
    }

    pub fn initramfs_path(&self) -> Option<&Path> {
        self.initramfs_path.as_deref()
    }

    pub fn kernel_cmdline(&self) -> &[String] {
        &self.kernel_cmdline
    }

    pub fn nested_virtualization(&self) -> bool {
        self.nested_virtualization
    }

    pub fn network(&self) -> &NetworkMode {
        &self.network
    }

    pub fn disks(&self) -> &[DiskImage] {
        &self.disks
    }

    pub fn mounts(&self) -> &[SharedDirectory] {
        &self.mounts
    }

    pub fn vsock_ports(&self) -> &[VsockPort] {
        &self.vsock_ports
    }

    pub fn krun(&self) -> &KrunOptions {
        &self.krun
    }

    pub fn vz(&self) -> &VzOptions {
        &self.vz
    }

    pub fn mock(&self) -> &MockOptions {
        &self.mock
    }

    /// Set the mock scenario path on an already-built config (used when the
    /// start request selects the mock backend after spec resolution).
    pub fn set_mock_scenario(&mut self, path: impl Into<PathBuf>) {
        self.mock.scenario = Some(path.into());
    }

    pub fn unix_datagram_network(&self) -> Option<(&PathBuf, [u8; 6])> {
        match &self.network {
            NetworkMode::UnixDatagram { peer_path, mac } => Some((peer_path, *mac)),
            _ => None,
        }
    }
}

/// Builder for [`VmConfig`]. All methods are chainable; `build` is infallible.
#[derive(Debug, Clone)]
pub struct VmConfigBuilder {
    config: VmConfig,
}

impl VmConfigBuilder {
    pub fn vm_id(mut self, vm_id: impl Into<String>) -> Self {
        self.config.vm_id = vm_id.into();
        self
    }

    pub fn base_directory(mut self, path: impl Into<PathBuf>) -> Self {
        self.config.base_directory = path.into();
        self
    }

    pub fn cpus(mut self, cpus: usize) -> Self {
        self.config.cpus = Some(cpus);
        self
    }

    pub fn memory(mut self, memory_mib: u64) -> Self {
        self.config.memory_mib = Some(memory_mib);
        self
    }

    pub fn kernel(mut self, path: impl Into<PathBuf>) -> Self {
        self.config.kernel_path = Some(path.into());
        self
    }

    pub fn initramfs(mut self, path: impl Into<PathBuf>) -> Self {
        self.config.initramfs_path = Some(path.into());
        self
    }

    pub fn kernel_cmdline(mut self, kernel_cmdline: Vec<String>) -> Self {
        self.config.kernel_cmdline = kernel_cmdline;
        self
    }

    pub fn nested_virtualization(mut self, enabled: bool) -> Self {
        self.config.nested_virtualization = enabled;
        self
    }

    pub fn network(mut self, network: NetworkMode) -> Self {
        self.config.network = network;
        self
    }

    pub fn no_network(mut self) -> Self {
        self.config.network = NetworkMode::None;
        self
    }

    pub fn unix_datagram_network(mut self, peer_path: impl Into<PathBuf>, mac: [u8; 6]) -> Self {
        self.config.network = NetworkMode::UnixDatagram {
            peer_path: peer_path.into(),
            mac,
        };
        self
    }

    pub fn unix_stream_network(mut self, path: impl Into<PathBuf>, mac: [u8; 6]) -> Self {
        self.config.network = NetworkMode::UnixStream {
            path: path.into(),
            mac,
        };
        self
    }

    pub fn tap_network(mut self, name: impl Into<String>, mac: [u8; 6]) -> Self {
        self.config.network = NetworkMode::Tap {
            name: name.into(),
            mac,
        };
        self
    }

    pub fn disk(mut self, disk: DiskImage) -> Self {
        self.config.disks.push(disk);
        self
    }

    pub fn mount(mut self, mount: SharedDirectory) -> Self {
        self.config.mounts.push(mount);
        self
    }

    pub fn vsock_port(mut self, port: VsockPort) -> Self {
        self.config.vsock_ports.push(port);
        self
    }

    /// Path to the krun helper binary (Linux backend only; ignored elsewhere).
    pub fn krun_path(mut self, path: impl Into<PathBuf>) -> Self {
        self.config.krun.helper_path = Some(path.into());
        self
    }

    /// Enable a Rosetta share (macOS backend only; ignored elsewhere).
    pub fn rosetta(mut self, enabled: bool) -> Self {
        self.config.vz.rosetta = enabled;
        self
    }

    /// Persisted machine identity (macOS backend only; ignored elsewhere).
    pub fn machine_identifier(mut self, machine_identifier: MachineIdentifier) -> Self {
        self.config.vz.machine_identifier = Some(machine_identifier);
        self
    }

    pub fn build(self) -> VmConfig {
        self.config
    }
}

/// Structural checks every backend applies before constructing a machine.
pub(crate) fn validate_common(config: &VmConfig) -> Result<(), VirtError> {
    let invalid = |reason: String| VirtError::InvalidConfig {
        name: config.name.clone(),
        reason,
    };

    if config.name.is_empty() {
        return Err(invalid("machine name must not be empty".to_string()));
    }
    if config.base_directory.as_os_str().is_empty() {
        return Err(invalid("base directory must not be empty".to_string()));
    }
    if config.kernel_path.is_none() {
        return Err(invalid("a kernel image is required".to_string()));
    }
    if config.cpus == Some(0) {
        return Err(invalid("cpu count must be nonzero".to_string()));
    }
    if config.memory_mib == Some(0) {
        return Err(invalid("memory size must be nonzero".to_string()));
    }

    let mut seen_ports = std::collections::HashSet::new();
    for vsock_port in &config.vsock_ports {
        if vsock_port.port == 0 {
            return Err(invalid("vsock port must be nonzero".to_string()));
        }
        if !seen_ports.insert(vsock_port.port) {
            return Err(invalid(format!(
                "vsock port {} is declared more than once",
                vsock_port.port
            )));
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn base_builder() -> VmConfigBuilder {
        VmConfig::builder("test-vm")
            .vm_id("vm-1")
            .base_directory("/tmp/test-vm")
            .kernel("/tmp/test-vm/vmlinux")
    }

    #[test]
    fn builder_maps_backend_sections() {
        let identifier = MachineIdentifier::from_bytes(vec![1, 2, 3]);
        let config = base_builder()
            .krun_path("/usr/libexec/krun")
            .rosetta(true)
            .machine_identifier(identifier.clone())
            .build();

        assert_eq!(
            config.krun().helper_path.as_deref(),
            Some(Path::new("/usr/libexec/krun"))
        );
        assert!(config.vz().rosetta);
        assert_eq!(config.vz().machine_identifier, Some(identifier));
    }

    #[test]
    fn builder_collects_devices_in_order() {
        let config = base_builder()
            .disk(DiskImage {
                path: "/tmp/a.img".into(),
                read_only: false,
            })
            .disk(DiskImage {
                path: "/tmp/b.img".into(),
                read_only: true,
            })
            .mount(SharedDirectory {
                host_path: "/tmp/share".into(),
                tag: "share".into(),
                read_only: true,
            })
            .vsock_port(VsockPort {
                port: 1027,
                mode: VsockPortMode::Connect,
            })
            .build();

        assert_eq!(config.disks().len(), 2);
        assert_eq!(config.disks()[0].path, PathBuf::from("/tmp/a.img"));
        assert!(config.disks()[1].read_only);
        assert_eq!(config.mounts()[0].tag, "share");
        assert_eq!(config.vsock_ports()[0].port, 1027);
    }

    #[test]
    fn validate_common_accepts_minimal_config() {
        let config = base_builder().build();
        assert!(validate_common(&config).is_ok());
    }

    #[test]
    fn validate_common_rejects_missing_kernel() {
        let config = VmConfig::builder("test-vm")
            .vm_id("vm-1")
            .base_directory("/tmp/test-vm")
            .build();
        assert!(matches!(
            validate_common(&config),
            Err(VirtError::InvalidConfig { .. })
        ));
    }

    #[test]
    fn validate_common_rejects_duplicate_vsock_ports() {
        let config = base_builder()
            .vsock_port(VsockPort {
                port: 1027,
                mode: VsockPortMode::Connect,
            })
            .vsock_port(VsockPort {
                port: 1027,
                mode: VsockPortMode::Listen,
            })
            .build();
        assert!(matches!(
            validate_common(&config),
            Err(VirtError::InvalidConfig { .. })
        ));
    }

    #[test]
    fn machine_identifier_write_back_marks_generated() {
        let identifier = MachineIdentifier::new();
        assert!(identifier.is_empty());
        assert!(!identifier.was_generated());

        identifier.set_generated_bytes(vec![7, 8, 9]);
        assert_eq!(identifier.bytes(), vec![7, 8, 9]);
        assert!(identifier.was_generated());
    }
}
